import React from 'react';
import { ItemIndicator } from '../Carousel.styles';

type CarouselIndicatorProps = {
  onClick: React.EventHandler<React.MouseEvent>;
  isActive: boolean;
};

export function CarouselIndicator({ onClick, isActive }: CarouselIndicatorProps) {
  return (
    <ItemIndicator
      onClick={onClick}
      data-testid="carousel-indicator"
      css={{
        width: isActive ? '1.375rem' : '0.5rem',
        backgroundColor: isActive ? '#0F7FFA' : '#DBDADA',
      }}
    />
  );
}
